def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    mask = objective[:, :, None] < objective[:, None, :]
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)
    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]
    pair_count = int(b_idx.numel())
    if pair_count <= 0:
        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear_clamped'})
    raw_weight = gap.clamp_min(0.0)
    clamp_lo = extra.get('clamp_lo', 0.25)
    clamp_hi = extra.get('clamp_hi', 4.0)
    weight = raw_weight.clamp(clamp_lo, clamp_hi)
    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear_clamped'})

